blocks.code:
CREATE CATALOG ecommerce;
USE CATALOG ecommerce;

CREATE SCHEMA ecommerce.silver;
CREATE SCHEMA IF NOT EXISTS ecommerce.silver;   -- idempotent

-- painful: one grant per person (×200 tables!)
GRANT SELECT ON TABLE prod.gold.daily_sales TO `nikos@company.com`;
GRANT SELECT ON TABLE prod.gold.daily_sales TO `maria@company.com`;
-- ... John, Eva ...

-- better: one grant to the group
GRANT SELECT
ON TABLE prod.gold.daily_sales
TO `analysts`;

GRANT USE CATALOG
ON CATALOG ecommerce
TO `analysts`;

GRANT USE CATALOG ON CATALOG ecommerce             TO `analysts`;
GRANT USE SCHEMA  ON SCHEMA  ecommerce.gold        TO `analysts`;
GRANT SELECT      ON TABLE   ecommerce.gold.daily_sales TO `analysts`;

-- now this works:
SELECT * FROM ecommerce.gold.daily_sales;

SHOW GRANTS ON TABLE  ecommerce.gold.daily_sales;
SHOW GRANTS ON SCHEMA ecommerce.gold;
SHOW GRANTS ON CATALOG ecommerce;

-- optional: filter by principal
SHOW GRANTS `analysts` ON SCHEMA ecommerce.gold;

REVOKE SELECT
ON TABLE ecommerce.gold.daily_sales
FROM `analysts`;

CREATE TABLE ecommerce.silver.legacy_orders
USING DELTA
LOCATION 's3://company/legacy/orders/';

CREATE CATALOG ecommerce
MANAGED LOCATION 's3://company-uc/ecommerce/';

CREATE SCHEMA ecommerce.finance
MANAGED LOCATION 's3://company-uc/ecommerce/finance/';

-- storage credentials are usually created by an admin
-- (Catalog Explorer / CLI / API) after the cloud IAM setup
SHOW STORAGE CREDENTIALS;

CREATE EXTERNAL LOCATION finance_loc
  URL 's3://company/finance/'
  WITH (STORAGE CREDENTIAL cred_a);

GRANT CREATE EXTERNAL TABLE
  ON EXTERNAL LOCATION finance_loc
  TO `data_engineers`;

-- managed volume: UC picks the storage location
CREATE VOLUME ecommerce.raw.documents;

-- external volume: you point at an existing path
CREATE EXTERNAL VOLUME ecommerce.raw.documents_ext
LOCATION 's3://company/documents/';

GRANT READ VOLUME
ON VOLUME ecommerce.raw.documents
TO `data_scientists`;

ALTER TABLE ecommerce.silver.customers
ALTER COLUMN email SET TAGS ('sensitivity' = 'pii');
-- an ABAC policy then masks every column tagged pii

-- sketch; deep dive in cross-organization sharing
CREATE SHARE ecommerce_share;
ALTER SHARE ecommerce_share ADD TABLE prod_ecommerce.gold.daily_revenue;
CREATE RECIPIENT partner_co;
GRANT SELECT ON SHARE ecommerce_share TO RECIPIENT partner_co;

-- engineers
GRANT USE CATALOG    ON CATALOG prod_ecommerce        TO `data_engineers`;
GRANT USE SCHEMA     ON SCHEMA  prod_ecommerce.silver TO `data_engineers`;
GRANT SELECT, MODIFY ON SCHEMA  prod_ecommerce.silver TO `data_engineers`;

-- analysts: Gold only
GRANT USE CATALOG ON CATALOG prod_ecommerce      TO `analysts`;
GRANT USE SCHEMA  ON SCHEMA  prod_ecommerce.gold TO `analysts`;
GRANT SELECT      ON SCHEMA  prod_ecommerce.gold TO `analysts`;

-- gold pipeline: read Silver, write Gold
GRANT USE CATALOG ON CATALOG prod_ecommerce        TO `gold_pipeline_sp`;
GRANT USE SCHEMA  ON SCHEMA  prod_ecommerce.silver TO `gold_pipeline_sp`;
GRANT SELECT      ON SCHEMA  prod_ecommerce.silver TO `gold_pipeline_sp`;
GRANT USE SCHEMA  ON SCHEMA  prod_ecommerce.gold   TO `gold_pipeline_sp`;
GRANT MODIFY      ON SCHEMA  prod_ecommerce.gold   TO `gold_pipeline_sp`;

CREATE CATALOG IF NOT EXISTS ecommerce_dev;

CREATE SCHEMA IF NOT EXISTS ecommerce_dev.bronze;
CREATE SCHEMA IF NOT EXISTS ecommerce_dev.silver;
CREATE SCHEMA IF NOT EXISTS ecommerce_dev.gold;
CREATE SCHEMA IF NOT EXISTS ecommerce_dev.files;

CREATE TABLE ecommerce_dev.silver.orders (
  order_id    BIGINT,
  customer_id BIGINT,
  amount      DECIMAL(10,2),
  country     STRING
);

CREATE VOLUME ecommerce_dev.files.incoming;

SHOW CATALOGS;
SHOW SCHEMAS IN ecommerce_dev;
SHOW TABLES  IN ecommerce_dev.silver;
DESCRIBE TABLE ecommerce_dev.silver.orders;

GRANT USE CATALOG ON CATALOG ecommerce_dev      TO `training_analysts`;
GRANT USE SCHEMA  ON SCHEMA  ecommerce_dev.gold TO `training_analysts`;
GRANT SELECT      ON SCHEMA  ecommerce_dev.gold TO `training_analysts`;

SHOW GRANTS ON SCHEMA ecommerce_dev.gold;

GRANT USE SCHEMA ON SCHEMA ecommerce_dev.files TO `data_engineers`;
GRANT READ VOLUME, WRITE VOLUME
ON VOLUME ecommerce_dev.files.incoming
TO `data_engineers`;
-- (data_engineers also need USE CATALOG on ecommerce_dev)

